return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ta_LK','project-id-version'=>'Babilim 1.2.2','pot-creation-date'=>'2026-11-09T07:54:38+00:00','po-revision-date'=>'2026-11-09T07:54:38+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'நீங்கள் Babilim ஐ இயக்கு என்பதை அழுத்தும்போதும், தளம் மீண்டும் புதிதாகப் பதிவு செய்ய வேண்டியிருந்தால் மீண்டும் அனுப்பப்படுவது: உங்கள் தளத்தின் URL, WordPress, PHP மற்றும் Babilim பதிப்புகள், உங்கள் தளத்தின் மொழி மற்றும் அதில் பயன்பாட்டில் உள்ள மொழிகள், மேலும் இந்தத் தளத்திற்காக உருவாக்கப்பட்ட ஒரு பொது விசை.','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'ஒவ்வொரு சரிபார்ப்பிலும் அனுப்பப்படுவது: நிறுவப்பட்ட செருகுநிரல்கள் மற்றும் தீம்களின் பட்டியல், அவற்றுக்காக நிறுவப்பட்ட Babilim மொழிபெயர்ப்புகளின் நிலை, பயன்பாட்டில் உள்ள மொழிகள் மற்றும் சிறிய கண்டறிதல் குறியீடுகள்.','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'ஒவ்வொரு கோரிக்கையிலும் உங்கள் தளத்தின் URL சேர்க்கப்படும், மேலும் சேவைக்குத் தேவைப்படும்போதெல்லாம் தளத்தின் அணுகல் டோக்கனும் சேர்க்கப்படும்.','What Babilim sends to the service'=>'Babilim சேவைக்கு அனுப்புவது என்ன','Your site\'s URL'=>'உங்கள் தளத்தின் URL','WordPress version'=>'WordPress பதிப்பு','PHP version'=>'PHP பதிப்பு','Babilim version'=>'Babilim பதிப்பு','Your site\'s language'=>'உங்கள் தளத்தின் மொழி','Languages in use on your site'=>'உங்கள் தளத்தில் பயன்பாட்டில் உள்ள மொழிகள்','A public key for this site'=>'இந்தத் தளத்திற்கான பொது விசை','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'இந்தத் தளத்திற்காக உருவாக்கப்பட்ட பொது விசை; கோரிக்கைகள் உண்மையில் இந்தத் தளத்திலிருந்தே வருகின்றன என்பதை நிரூபிக்கப் பயன்படுகிறது. பொதுப் பாதி மட்டுமே அனுப்பப்படும்; தனிப் பாதி உங்கள் தளத்திலேயே இருக்கும்.','Installed plugins and themes'=>'நிறுவப்பட்ட செருகுநிரல்கள் மற்றும் தீம்கள்','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, and the languages it already includes. For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'நிறுவப்பட்ட ஒவ்வொரு செருகுநிரல் மற்றும் தீமுக்கும்: அதன் பெயர் (slug), பதிப்பு, text domain, அது WordPress.org இல் பட்டியலிடப்பட்டுள்ளதா என்பது, மற்றும் அது ஏற்கனவே கொண்டுள்ள மொழிகள். நீங்கள் நிறுவிய ஒவ்வொரு Babilim மொழிபெயர்ப்புக்கும்: அது எந்தப் பதிப்பு, கடைசியாக எப்போது சரிபார்க்கப்பட்டது, அதன் கோப்புச் சரிபார்ப்பில் தேர்ச்சி பெற்றதா என்பது.','Source files (only if you confirm an upload)'=>'மூலக் கோப்புகள் (பதிவேற்றத்தை உறுதிப்படுத்தினால் மட்டும்)','Diagnostic codes'=>'கண்டறிதல் குறியீடுகள்','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'அதிகபட்சம் 20 சிறிய கண்டறிதல் குறியீடுகள் (எடுத்துக்காட்டாக, சரிபார்ப்பில் தோல்வியடைந்த மொழிபெயர்ப்புக் கோப்பு), ஒவ்வொன்றுடனும் செருகுநிரல் அல்லது தீம், மொழி மற்றும் அது நிகழ்ந்த நேரம். அவற்றில் உங்கள் தளத்தின் எந்த உரையும் அல்லது மொழிபெயர்க்கப்பட்ட உரையும் ஒருபோதும் இருக்காது.','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'இந்த நெட்வொர்க்கில் %1$d தளம், செருகுநிரல் நீக்கப்படும்போது தனது Babilim அடையாளத்தை அழிக்கும்படி அமைக்கப்பட்டுள்ளது. அந்தத் தளத்துடன் இணைக்கப்பட்ட கட்டண உரிமத்தை அதன்பிறகு தானாக மீட்டெடுக்க முடியாது; %2$s என்ற முகவரியில் Babilim ஆதரவைத் தொடர்பு கொள்ள வேண்டும். அடையாளத்தைத் தக்கவைக்க, ரத்துசெய் என்பதை அழுத்தி, அந்தத் தளத்தின் Babilim அமைப்புகளில் "நிறுவல் நீக்கும்போது Babilim தரவு அனைத்தையும் நீக்கு" என்பதைத் தேர்வுநீக்கி, மீண்டும் செயலிழக்கச் செய்யுங்கள். எப்படியும் செயலிழக்கச் செய்யவா?' . "\0" . 'இந்த நெட்வொர்க்கில் %1$d தளங்கள், செருகுநிரல் நீக்கப்படும்போது தங்கள் Babilim அடையாளத்தை அழிக்கும்படி அமைக்கப்பட்டுள்ளன. அந்தத் தளங்களுடன் இணைக்கப்பட்ட கட்டண உரிமங்களை அதன்பிறகு தானாக மீட்டெடுக்க முடியாது; %2$s என்ற முகவரியில் Babilim ஆதரவைத் தொடர்பு கொள்ள வேண்டும். அடையாளங்களைத் தக்கவைக்க, ரத்துசெய் என்பதை அழுத்தி, ஒவ்வொரு தளத்தின் Babilim அமைப்புகளிலும் "நிறுவல் நீக்கும்போது Babilim தரவு அனைத்தையும் நீக்கு" என்பதைத் தேர்வுநீக்கி, மீண்டும் செயலிழக்கச் செய்யுங்கள். எப்படியும் செயலிழக்கச் செய்யவா?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s செய்ய எதுவும் இல்லை.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. மொழியைத் தேர்ந்தெடுக்கவும்.','%d failed'=>'%d தோல்வி' . "\0" . '%d தோல்வி','%d not yet tried'=>'%d இன்னும் முயற்சிக்கப்படவில்லை' . "\0" . '%d இன்னும் முயற்சிக்கப்படவில்லை','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d அறிக்கை காத்திருக்கிறது. "Always share" மற்றும் "Don\'t share" அவை அனைத்திற்கும் பொருந்தும்.' . "\0" . '%d அறிக்கைகள் காத்திருக்கின்றன. "Always share" மற்றும் "Don\'t share" அவை அனைத்திற்கும் பொருந்தும்.','%d skipped'=>'%d தவிர்க்கப்பட்டது' . "\0" . '%d தவிர்க்கப்பட்டன','%d succeeded'=>'%d வெற்றி' . "\0" . '%d வெற்றி','%d to install'=>'%d நிறுவப்பட உள்ளது' . "\0" . '%d நிறுவப்பட உள்ளன','(a public key generated for this site)'=>'(இந்தத் தளத்திற்காக உருவாக்கப்பட்ட பொதுத் திறவு)','(detected)'=>'(கண்டறியப்பட்டது)','(generic codes and coordinates only)'=>'(பொதுக் குறியீடுகளும் ஆயத்தொலைவுகளும் மட்டும்)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s அன்று ஒரு சுத்தப்படுத்தல் நிறுத்தப்பட்டது: %2$s. எதுவும் நீக்கப்படவில்லை.','A file in the component could not be read, so it was not packaged.'=>'கூறில் உள்ள ஒரு கோப்பைப் படிக்க முடியவில்லை, எனவே அது தொகுக்கப்படவில்லை.','A host that serves only one PHP request at a time cannot complete this step.'=>'ஒரு நேரத்தில் ஒரு PHP கோரிக்கையை மட்டுமே வழங்கும் ஹோஸ்ட்டால் இந்தப் படியை முடிக்க முடியாது.','A part of the upload kept failing, so the upload was cancelled.'=>'பதிவேற்றத்தின் ஒரு பகுதி தொடர்ந்து தோல்வியடைந்ததால் பதிவேற்றம் ரத்து செய்யப்பட்டது.','A translation cannot be requested for that locale on this site right now.'=>'இந்தத் தளத்தில் அந்த மொழிக்கு இப்போது மொழிபெயர்ப்பைக் கோர முடியாது.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'%1$s அன்று (%2$s) மொழிபெயர்ப்புச் சுட்டெண் எழுதுதல் மற்றொரு கோரிக்கையுடன் முரண்பட்டு பயன்படுத்தப்படவில்லை; மிகச் சமீபத்திய பதிப்பு வைக்கப்பட்டது.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'%1$s அன்று (%2$s) மொழிபெயர்ப்புச் சுட்டெண் எழுதுதலை முடிக்க முடியவில்லை, அது பயன்படுத்தப்படவில்லை (%3$s).','Account'=>'கணக்கு','Add another language'=>'மற்றொரு மொழியைச் சேர்','Advanced'=>'மேம்பட்டவை','All'=>'அனைத்தும்','All free-plan slots for this site are used'=>'இந்தத் தளத்தின் அனைத்து இலவசத் திட்ட இடங்களும் பயன்பாட்டில் உள்ளன','All languages'=>'அனைத்து மொழிகளும்','Already in WordPress core'=>'ஏற்கனவே WordPress மையத்தில் உள்ளது','Already installed.'=>'ஏற்கனவே நிறுவப்பட்டுள்ளது.','Always share'=>'Always share','Another installation is running; try again in a moment.'=>'மற்றொரு நிறுவல் இயங்குகிறது; சிறிது நேரத்தில் மீண்டும் முயலவும்.','Automatic installs'=>'தானியங்கி நிறுவல்கள்','Automatic installs are now off; turn them on again in the settings if you want them.'=>'தானியங்கி நிறுவல்கள் இப்போது அணைக்கப்பட்டுள்ளன; தேவைப்பட்டால் அமைப்புகளில் மீண்டும் இயக்குங்கள்.','Available'=>'கிடைக்கிறது','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'கிடைக்கும் மொழிபெயர்ப்புகளை ஒரே கிளிக்கில் நிறுவலாம்; காணாமல் போனவற்றைக் கோரலாம். தானியங்கி நிறுவல்கள் இயக்கத்தில் இருக்கும்போது, நீங்கள் நிர்வகிக்கும் மொழிகளுக்குச் சேவை கிடைப்பதாகப் பட்டியலிடும் மொழிபெயர்ப்புகள் தினமும் இருமுறை ஒத்திசைவின்போது நிறுவப்படும்.','Available · %s'=>'கிடைக்கிறது · %s','Babilim'=>'Babilim','Babilim Settings'=>'Babilim அமைப்புகள்','Babilim adds translations for every language checked here.'=>'இங்கே தேர்ந்தெடுக்கப்பட்ட ஒவ்வொரு மொழிக்கும் Babilim மொழிபெயர்ப்புகளைச் சேர்க்கும்.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim வலைத்தளத்திற்கு வெளியே ஒரு தற்காலிகக் கோப்புறையை உறுதிப்படுத்த முடியவில்லை, எனவே கூறு தொகுக்கப்படவில்லை, எதுவும் பதிவேற்றப்படவில்லை. வலை ரூட்டிற்கு வெளியே எழுதக்கூடிய கோப்புறையாக wp-config.php இல் BABILIM_TEMP_DIR ஐ வரையறுக்கவும் (எடுத்துக்காட்டாக, உங்கள் தளத்தின் பொது அடைவுக்குள் அல்லாமல் அதன் அருகில் உள்ள கோப்புறை), அல்லது உங்கள் ஹோஸ்டிடம் ஒன்றைக் கேளுங்கள்.','Babilim could not finish checking this site.'=>'Babilim இந்தத் தளத்தைச் சரிபார்த்து முடிக்க முடியவில்லை.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim இயக்குவதை முடிக்க முடியவில்லை (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'இந்தத் தளத்தைச் சரிபார்த்து முடிக்க Babilim-ஆல் இயலவில்லை (சேவை மீண்டும் தளத்தை அணுக முடியவில்லை). பதிவு இடைநிறுத்தப்பட்டுள்ளது.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim இந்தத் தளத்தைச் சரிபார்க்க முடியவில்லை, எனவே சரிபார்ப்பு வெற்றிபெறும் வரை எதுவும் பதிவிறக்கமோ நிறுவலோ செய்யப்படாது.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim இந்தத் தளத்தைச் சரிபார்க்க முடியவில்லை, எனவே எதுவும் பதிவிறக்கப்படவோ நிறுவப்படவோ இல்லை.','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'உங்கள் மொழிக்கு மொழிபெயர்ப்பு இல்லாத இந்தத் தளத்திலுள்ள செருகுநிரல்கள் மற்றும் தீம்களுக்கான மொழிபெயர்ப்புகளை Babilim சேவையிலிருந்து Babilim பெற்று, உங்கள் சேவைத் திட்டம் உள்ளடக்கியவற்றை நிறுவுகிறது.','Babilim has not been enabled for this site yet.'=>'இந்தத் தளத்திற்கு Babilim இன்னும் இயக்கப்படவில்லை.','Babilim has not installed any translation for this language.'=>'இந்த மொழிக்கு Babilim எந்த மொழிபெயர்ப்பையும் நிறுவவில்லை.','Babilim hit an error. Share an error report?'=>'Babilim-இல் பிழை ஏற்பட்டது. பிழை அறிக்கையைப் பகிரலாமா?','Babilim installed %d translation automatically since your last visit.'=>'உங்கள் கடைசி வருகைக்குப் பிறகு Babilim %d மொழிபெயர்ப்பைத் தானாக நிறுவியது.' . "\0" . 'உங்கள் கடைசி வருகைக்குப் பிறகு Babilim %d மொழிபெயர்ப்புகளைத் தானாக நிறுவியது.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim முடக்கப்பட்டுள்ளது. இனி எதுவும் அனுப்பப்படாது; ஏற்கெனவே நிறுவப்பட்ட மொழிபெயர்ப்புகள் தொடர்ந்து செயல்படும்.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim இயக்கப்பட்டது: இந்தத் தளம் சரிபார்க்கப்பட்டது, %d கூறு கண்டறியப்பட்டது.' . "\0" . 'Babilim இயக்கப்பட்டது: இந்தத் தளம் சரிபார்க்கப்பட்டது, %d கூறுகள் கண்டறியப்பட்டன.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim இந்தத் தளத்தை இயக்கிச் சரிபார்க்கிறது… (கடைசி முயற்சி: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim இந்தத் தளத்தை இயக்கிச் சரிபார்க்கிறது… இந்தப் பக்கத்தை மீண்டும் ஏற்றவும் அல்லது திட்டமிட்ட சரிபார்ப்பு முடியும் வரை காத்திருக்கவும்.','Babilim is not enabled.'=>'Babilim இயக்கப்படவில்லை.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'செருகுநிரல் நீக்கப்படும்போது இந்தத் தளத்தின் Babilim அடையாளத்தை அழிக்கும்படி Babilim அமைக்கப்பட்டுள்ளது. இந்தத் தளத்துடன் இணைக்கப்பட்ட கட்டண உரிமத்தை அதன்பிறகு தானாக மீட்டெடுக்க முடியாது; %s என்ற முகவரியில் Babilim ஆதரவைத் தொடர்பு கொள்ள வேண்டும். அடையாளத்தைத் தக்கவைக்க, ரத்துசெய் என்பதை அழுத்தி, Babilim அமைப்புகளில் "நிறுவல் நீக்கும்போது Babilim தரவு அனைத்தையும் நீக்கு" என்பதைத் தேர்வுநீக்கி, மீண்டும் செயலிழக்கச் செய்யுங்கள். எப்படியும் செயலிழக்கச் செய்யவா?','Babilim ran out of time for this step and will continue on the next check.'=>'இந்தப் படிக்கு Babilim க்கு நேரம் போதவில்லை; அடுத்த சரிபார்ப்பில் தொடரும்.','Babilim settings'=>'Babilim அமைப்புகள்','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim ஒத்திசைவு சேவையால் தற்காலிகமாகத் தாமதமாகிறது (வீத வரம்பு); %s க்குப் பிறகு மீண்டும் முயலும்.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'இந்தப் பதிவேற்றம் காத்திருந்தபோது Babilim புதுப்பிக்கப்பட்டது. பழைய தொகுப்பு நிராகரிக்கப்பட்டது; பதிவேற்றத்தை மீண்டும் உறுதிப்படுத்தவும்.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim %1$s (பதிப்பு %2$s) இலிருந்து இந்தக் கோப்புகளைப் பதிவேற்றும்: ஒவ்வொரு .php மற்றும் .js கோப்பு, ஒவ்வொரு block.json கோப்பு, மற்றும் அதன் முதன்மைக் கோப்புறையில் உள்ள readme.txt, readme.md, style.css மற்றும் theme.json. மொழிபெயர்க்க வேண்டிய உரையைக் கண்டறியவும், செருகுநிரல் அல்லது தீமை அடையாளம் காணவும் இவை பயன்படுத்தப்படுகின்றன.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest கிடைக்கவில்லை: %s','Back'=>'பின்செல்','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'இந்த இணையக் களத்திற்கு முன்பு உரிமம் வாங்கினீர்களா? பணம் செலுத்தும்போது பெற்ற மீட்டெடுப்புக் குறியீட்டை உள்ளிடவும்.','Broken placeholder'=>'உடைந்த இடஒதுக்கி','Build'=>'பில்ட்','Built'=>'உருவாக்கப்பட்டது','Bulk actions apply only to the selected language of each selected component.'=>'தேர்ந்தெடுக்கப்பட்ட ஒவ்வொரு கூறின் தேர்ந்தெடுக்கப்பட்ட மொழிக்கு மட்டுமே மொத்தச் செயல்கள் பொருந்தும்.','Bulk actions apply to every matching language of each selected component.'=>'தேர்ந்தெடுக்கப்பட்ட ஒவ்வொரு கூறின் பொருந்தும் அனைத்து மொழிகளுக்கும் மொத்தச் செயல்கள் பொருந்தும்.','Bulk download:'=>'மொத்தப் பதிவிறக்கம்:','Bulk request:'=>'மொத்தக் கோரிக்கை:','Bulk update:'=>'மொத்தப் புதுப்பிப்பு:','Bundled with the plugin'=>'செருகுநிரலுடன் இணைக்கப்பட்டது','Bundled with the theme'=>'தீமுடன் இணைக்கப்பட்டது','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Enable என்பதைக் கிளிக் செய்வதன் மூலம், மேலே பட்டியலிடப்பட்ட தகவலை Babilim க்கு அனுப்ப ஒப்புக்கொள்கிறீர்கள்.','By continuing you confirm that you have the right to upload this component.'=>'தொடர்வதன் மூலம், இந்தக் கூறைப் பதிவேற்ற உங்களுக்கு உரிமை உள்ளது என்பதை உறுதிப்படுத்துகிறீர்கள்.','Cancel'=>'ரத்துசெய்','Category'=>'வகை','Check again'=>'மீண்டும் சரிபார்','Check again now'=>'இப்போது மீண்டும் சரிபார்','Checkout is not available for this site right now.'=>'இந்தத் தளத்திற்கு இப்போது பணம் செலுத்துதல் கிடைக்கவில்லை.','Choose'=>'தேர்ந்தெடு','Choose a category…'=>'ஒரு வகையைத் தேர்ந்தெடுக்கவும்…','Choose a language'=>'மொழியைத் தேர்ந்தெடுக்கவும்','Choose a language…'=>'மொழியைத் தேர்ந்தெடுக்கவும்…','Clear filters'=>'வடிகட்டிகளை அழி','Close'=>'மூடு','Component'=>'கூறு','Confirm'=>'உறுதிப்படுத்து','Conflicting keys'=>'முரண்படும் விசைகள்','Continue'=>'தொடர்','Continue next batch (%d left)'=>'அடுத்த தொகுதியைத் தொடரவும் (%d மீதமுள்ளன)','Continuing…'=>'தொடர்கிறது…','Could not back up %s before replacing it.'=>'%s ஐ மாற்றுவதற்கு முன் காப்புப்பிரதி எடுக்க முடியவில்லை.','Could not create the package archive.'=>'தொகுப்புக் காப்பகத்தை உருவாக்க முடியவில்லை.','Could not determine active components; the existing merged index was left unchanged.'=>'செயலில் உள்ள கூறுகளைத் தீர்மானிக்க முடியவில்லை; ஏற்கனவே உள்ள ஒன்றிணைந்த சுட்டெண் மாற்றப்படாமல் விடப்பட்டது.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'நிறுவப்பட்ட செருகுநிரல்கள்/தீம்களைத் தீர்மானிக்க முடியவில்லை; துடைப்பு தவிர்க்கப்பட்டது, எதுவும் நீக்கப்படவில்லை.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'சேவையிலிருந்து முழு WordPress.org மொழிப் பட்டியலை ஏற்ற முடியவில்லை, எனவே இப்போது வேறு மொழியைச் சேர்க்க முடியாது.','Could not move %s into place.'=>'%s ஐ உரிய இடத்திற்கு நகர்த்த முடியவில்லை.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' க்கான ஒன்றிணைந்த சுட்டெண்ணை இடத்திற்கு நகர்த்த முடியவில்லை; முந்தைய வழங்கப்பட்ட சுட்டெண் (இருந்தால்) பாதி புதுப்பிக்கப்பட்ட நிலையில் விடப்படாமல் நீக்கப்பட்டது. அடுத்த வெற்றிகரமான மறுகட்டமைப்பு வரை இந்த மொழிக்கு இயல்புநிலை டொமைன் துணைத் தொகுப்பு வழங்கப்படாது.','Could not open zip: %s'=>'zip ஐத் திறக்க முடியவில்லை: %s','Could not prepare %s for rollback.'=>'%s ஐ முந்தைய நிலைக்கு மீட்டமைக்கத் தயார்படுத்த இயலவில்லை.','Could not read %s back after moving it into place.'=>'%s ஐ இடத்தில் நகர்த்திய பின் மீண்டும் படிக்க இயலவில்லை.','Could not read: %s'=>'படிக்க முடியவில்லை: %s','Could not restore the purchase: %s'=>'கொள்முதலை மீட்டெடுக்க முடியவில்லை: %s','Could not show a new restore code: %s'=>'புதிய மீட்டெடுப்புக் குறியீட்டைக் காட்ட முடியவில்லை: %s','Could not stage %s'=>'%s ஐ ஸ்டேஜ் செய்ய முடியவில்லை','Could not stage default/%s'=>'default/%s ஐ ஸ்டேஜ் செய்ய முடியவில்லை','Could not start checkout: %s'=>'பணம் செலுத்துதலைத் தொடங்க முடியவில்லை: %s','Could not verify entry count for %s'=>'%s க்கான உள்ளீடுகளின் எண்ணிக்கையைச் சரிபார்க்க முடியவில்லை','Could not write the downloaded package to disk.'=>'பதிவிறக்கிய தொகுப்பை வட்டில் எழுத முடியவில்லை.','Could not write the staged merged index.'=>'தயார்நிலையில் உள்ள ஒன்றிணைந்த சுட்டெண்ணை எழுத முடியவில்லை.','Current translation'=>'தற்போதைய மொழிபெயர்ப்பு','Custom overrides'=>'தனிப்பயன் மேலெழுதல்கள்','Danger zone'=>'ஆபத்துப் பகுதி','Default supplement entry count mismatch.'=>'இயல்பிருப்பு துணைப்பகுதி உள்ளீடுகளின் எண்ணிக்கை பொருந்தவில்லை.','Delete all Babilim data on uninstall'=>'நிறுவல் நீக்கும்போது Babilim தரவு அனைத்தையும் நீக்கு','Disable Babilim'=>'Babilim ஐ முடக்கு','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim ஐ முடக்கவா? நிறுவப்பட்ட மொழிபெயர்ப்புகள் வைக்கப்படும், ஆனால் இனி சரிபார்ப்புகளோ பதிவிறக்கங்களோ நடக்காது.','Don\'t share'=>'Don\'t share','Download'=>'பதிவிறக்கு','Downloaded and installed.'=>'பதிவிறக்கி நிறுவப்பட்டது.','Downloading…'=>'பதிவிறக்குகிறது…','Downloads: %1$d/%2$d (%3$s)'=>'பதிவிறக்கங்கள்: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'ஒவ்வொரு கூறும் ஒவ்வொரு மொழிக்கான பகிரப்பட்ட இயல்புநிலை டொமைன் துணைத் தொகுப்பில் அளிக்கும் தனிப்பட்ட பங்களிப்பு.','Enable Babilim'=>'Babilim ஐ இயக்கு','Enabling…'=>'இயக்குகிறது…','English (United States)'=>'ஆங்கிலம் (அமெரிக்க ஐக்கிய நாடுகள்)','Entries'=>'உள்ளீடுகள்','Entry count mismatch for %s'=>'%s க்கான உள்ளீடுகளின் எண்ணிக்கை பொருந்தவில்லை','Error reports'=>'பிழை அறிக்கைகள்','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'இந்தத் தளத்தில் பயன்பாட்டில் உள்ள ஒவ்வொரு மொழிப்பகுதியும் (தளத்தின் மொழிப்பகுதி, நிறுவப்பட்ட மொழித் தொகுப்புகள், பயனர் மொழிப்பகுதிகள், நீங்கள் கைமுறையாகச் சேர்த்தவை). எந்த மொழிப்பகுதியும் மற்றொன்றிலிருந்து வேறுபடுத்தி நடத்தப்படுவதில்லை.','Excluded'=>'விலக்கப்பட்டது','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'வேறு பெயர்கள் அல்லது நீட்சிகள் கொண்ட கோப்புகளும், uploads, cache, logs, backup, data, vendor, node_modules மற்றும் languages கோப்புறைகளும், மறைக்கப்பட்ட கோப்புகளும், பொதுவான ரகசியங்களுடன் பெயர் பொருந்தும் கோப்புகளும் (wp-config*, .env*, *.sql, *.log, *.pem, *.key) சேர்க்கப்படாது. குறியீட்டுக் கோப்புகளில் நீங்கள் பகிர விரும்பாத உரை அல்லது தரவு இன்னும் இருக்கக்கூடும்; உறுதியாகத் தெரியவில்லை என்றால் அவற்றைச் சரிபார்க்கவும். கோப்புகள் சேவையை வந்தடைந்ததும், சேவை அதே வகையான கோப்புகளை மீண்டும் நீக்குகிறது.','Fills in missing translations for the plugins and themes already installed on your site.'=>'உங்கள் தளத்தில் ஏற்கெனவே நிறுவப்பட்டுள்ள செருகுநிரல்கள் மற்றும் தீம்களுக்கு விடுபட்ட மொழிபெயர்ப்புகளை நிரப்புகிறது.','Free'=>'இலவசம்','Free-plan slots'=>'இலவசத் திட்ட இடங்கள்','General'=>'பொது','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'இது இயக்கப்பட்டிருந்தால், நிறுவல் நீக்கும்போது இந்தத் தளத்தின் அடையாளமும் அழிக்கப்படும். இந்தத் தளத்துடன் இணைக்கப்பட்ட கட்டண உரிமத்தை அதன்பிறகு தானாக மீட்டெடுக்க முடியாது; அதை மீண்டும் பெற %s என்ற முகவரியில் Babilim ஆதரவைத் தொடர்பு கொள்ள வேண்டும்.','Included'=>'சேர்க்கப்பட்டவை','Included in index'=>'சுட்டெண்ணில் சேர்க்கப்பட்டுள்ளது','Install available translations automatically'=>'கிடைக்கும் மொழிபெயர்ப்புகளைத் தானாக நிறுவு','Installed'=>'நிறுவப்பட்டது','Installed translations are kept, but no further checks or downloads will run.'=>'நிறுவப்பட்ட மொழிபெயர்ப்புகள் வைத்திருக்கப்படும், ஆனால் மேலும் சரிபார்ப்புகளோ பதிவிறக்கங்களோ நடைபெறாது.','Installed · %s'=>'நிறுவப்பட்டது · %s','Installed · built for %1$s, this site has %2$s'=>'நிறுவப்பட்டது · %1$s க்காக உருவாக்கப்பட்டது, இந்தத் தளத்தில் %2$s உள்ளது','Installed · built for %s'=>'நிறுவப்பட்டது · %s க்காக உருவாக்கப்பட்டது','Installed · built for %s, new version failed'=>'நிறுவப்பட்டது · %s க்காக உருவாக்கப்பட்டது, புதிய பதிப்பு தோல்வியடைந்தது','Installed · built for %s, new version scheduled'=>'நிறுவப்பட்டது · %s க்காக உருவாக்கப்பட்டது, புதிய பதிப்பு திட்டமிடப்பட்டுள்ளது','Installed · built for %s, translating the new version…'=>'நிறுவப்பட்டது · %s க்காக உருவாக்கப்பட்டது, புதிய பதிப்பு மொழிபெயர்க்கப்படுகிறது…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'நிறுவப்பட்டது · %s பதிப்பிற்காக உருவாக்கப்பட்டது; இந்தச் செருகுநிரல் அல்லது தீம் இனி தளத்தின் சேவைத் திட்டத்தில் உள்ளடங்காது','Installed · built for a different version'=>'நிறுவப்பட்டது · வேறு பதிப்பிற்காக உருவாக்கப்பட்டது','Installed · built for a different version, new version failed'=>'நிறுவப்பட்டது · வேறு பதிப்பிற்காக உருவாக்கப்பட்டது, புதிய பதிப்பு தோல்வியடைந்தது','Installed · built for a different version, new version scheduled'=>'நிறுவப்பட்டது · வேறு பதிப்பிற்காக உருவாக்கப்பட்டது, புதிய பதிப்பு திட்டமிடப்பட்டுள்ளது','Installed · built for a different version, translating the new version…'=>'நிறுவப்பட்டது · வேறு பதிப்பிற்காக உருவாக்கப்பட்டது, புதிய பதிப்பு மொழிபெயர்க்கப்படுகிறது…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'நிறுவப்பட்டது · வேறு பதிப்பிற்காக உருவாக்கப்பட்டது; இந்தச் செருகுநிரல் அல்லது தீம் இனி தளத்தின் சேவைத் திட்டத்தில் உள்ளடங்காது','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'இது சேவையின் ஹோஸ்டிங் வழங்குநரால் சேமிக்கப்பட்டு, மொழிபெயர்ப்பை உருவாக்க AI மாதிரிகளால் செயலாக்கப்படும்.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'அனைத்தையும் அழிக்கும்போதோ இந்தச் செருகுநிரலை நிறுவல் நீக்கும்போதோ என் சொந்த மொழிபெயர்ப்பு மேலெழுதல்களை வைத்திரு.','Language'=>'மொழி','Language:'=>'மொழி:','Languages'=>'மொழிகள்','Languages found on this site: %s.'=>'இந்தத் தளத்தில் கண்டறியப்பட்ட மொழிகள்: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'%1$s அன்றைய கடைசி சுத்தப்படுத்தல்: %2$d புதிதாகக் குறிக்கப்பட்டவை, %3$d கோப்பு(கள்) நீக்கப்பட்டன, %4$d பதிவு(கள்) அகற்றப்பட்டன.','Maintenance'=>'பராமரிப்பு','Maintenance status is not available right now.'=>'பராமரிப்பு நிலை இப்போது கிடைக்கவில்லை.','Manifest unavailable: %s'=>'மேனிஃபெஸ்ட் கிடைக்கவில்லை: %s','Negation reversed'=>'எதிர்மறை தலைகீழாக்கப்பட்டது','No'=>'இல்லை','No build is available to download for this locale.'=>'இந்த மொழிக்குப் பதிவிறக்க எந்தப் பதிப்பும் இல்லை.','No cleanup has run yet.'=>'இதுவரை சுத்தப்படுத்தல் எதுவும் இயங்கவில்லை.','No components match these filters. %s'=>'இந்த வடிகட்டிகளுக்குப் பொருந்தும் கூறுகள் எதுவும் இல்லை. %s','No components synced yet.'=>'இதுவரை கூறுகள் எதுவும் ஒத்திசைக்கப்படவில்லை.','No installed translation matches.'=>'பொருந்தும் நிறுவப்பட்ட மொழிபெயர்ப்பு எதுவும் இல்லை.','No language is managed yet.'=>'இன்னும் எந்த மொழியும் நிர்வகிக்கப்படவில்லை.','No pending challenge for this nonce.'=>'இந்த நான்ஸுக்கு நிலுவையில் உள்ள சவால் எதுவும் இல்லை.','No pending challenge to verify.'=>'சரிபார்க்க நிலுவையில் உள்ள சவால் எதுவும் இல்லை.','No plugins or themes found.'=>'செருகுநிரல்கள் அல்லது தீம்கள் எதுவும் கிடைக்கவில்லை.','No previous build to roll back to.'=>'முந்தைய நிலைக்கு மீட்டமைக்க முந்தைய பில்ட் எதுவும் இல்லை.','No record for %s'=>'%s க்கான பதிவு எதுவும் இல்லை','No site id is on file to rotate a token for.'=>'டோக்கனை மாற்றுவதற்கான தள அடையாளம் எதுவும் பதிவில் இல்லை.','No — component inactive'=>'இல்லை — கூறு செயலில் இல்லை','No — component removed'=>'இல்லை — கூறு நீக்கப்பட்டது','No — installed version differs from the active one'=>'இல்லை — நிறுவப்பட்ட பதிப்பு செயலில் உள்ளதிலிருந்து வேறுபடுகிறது','Not a valid server_build_id: %s'=>'சரியான server_build_id அல்ல: %s','Not covered by the free service plan'=>'இலவச சேவைத் திட்டத்தில் உள்ளடங்காதவை','Not installed'=>'நிறுவப்படவில்லை','Not registered yet'=>'இன்னும் பதிவு செய்யப்படவில்லை','Not supported'=>'ஆதரிக்கப்படவில்லை','Not verified'=>'சரிபார்க்கப்படவில்லை','Note (optional)'=>'குறிப்பு (விருப்பத்திற்குரியது)','Nothing to choose.'=>'தேர்ந்தெடுக்க எதுவும் இல்லை.','Nothing to confirm.'=>'உறுதிப்படுத்த எதுவும் இல்லை.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'இயல்பாக முடக்கத்தில் உள்ளது: செருகுநிரலை நீக்கினாலும் இந்தத் தளத்தின் அடையாளம் வைக்கப்படும், எனவே மீண்டும் நிறுவும்போது அதை மறுபயன்படுத்தலாம்.','One or more served files no longer match the manifest.'=>'வழங்கப்பட்ட ஒன்று அல்லது அதற்கு மேற்பட்ட கோப்புகள் இனி மேனிஃபெஸ்ட்டுடன் பொருந்தவில்லை.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'இந்தத் தளத்திற்கான ஒருமுறை கொள்முதல்: %1$s %2$s. எதிர்கால மொழிபெயர்ப்பு புதுப்பிப்புகள் அனைத்தும் இதில் அடங்கும். கட்டணம் புதிய தாவலில் Paddle மூலம் கையாளப்படும்.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'இதை நெட்வொர்க் நிர்வாகி மட்டுமே செய்ய முடியும், ஏனெனில் இது இந்த நெட்வொர்க்கில் உள்ள அனைத்து தளங்களும் பகிரும் மொழிபெயர்ப்புக் கோப்புகளை மாற்றுகிறது.','Only plugins and themes can be packaged.'=>'செருகுநிரல்களையும் தீம்களையும் மட்டுமே தொகுக்க முடியும்.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'WordPress.org இல் இல்லாத செருகுநிரல் அல்லது தீமுக்கான பதிவேற்றத்தை நீங்கள் உறுதிப்படுத்தும்போது மட்டும்: ஒவ்வொரு .php கோப்பும், ஒவ்வொரு .js கோப்பும், ஒவ்வொரு block.json கோப்பும், அந்தக் கூறின் முதன்மைக் கோப்புறையில் உள்ள readme.txt, readme.md, style.css மற்றும் theme.json கோப்புகளும், பொதுவான ரகசியங்களுடன் பொருந்தும் கோப்புகள் விலக்கப்பட்ட பிறகு, ஒரு zip ஆக.','Open Babilim settings'=>'Babilim அமைப்புகளைத் திறக்கவும்','Original language'=>'மூல மொழி','Original string'=>'மூலச் சரம்','Paid'=>'கட்டணம்','Partner'=>'கூட்டாளர்','Please check that your site can be reached from the internet, then try again.'=>'உங்கள் தளத்தை இணையத்திலிருந்து அணுக முடியும் என்பதைச் சரிபார்த்து, மீண்டும் முயற்சிக்கவும்.','Please choose a category for this report.'=>'இந்தப் புகாருக்கு ஒரு வகையைத் தேர்ந்தெடுக்கவும்.','Plugin'=>'செருகுநிரல்','Plugin · %s'=>'செருகுநிரல் · %s','Plugins'=>'செருகுநிரல்கள்','Preview'=>'முன்னோட்டம்','Purchase restored. This site is now licensed.'=>'கொள்முதல் மீட்டெடுக்கப்பட்டது. இந்தத் தளம் இப்போது உரிமம் பெற்றது.','Re-parsed entry count did not match the built index.'=>'மீண்டும் பகுப்பாய்வு செய்யப்பட்ட உள்ளீடுகளின் எண்ணிக்கை உருவாக்கப்பட்ட சுட்டியுடன் பொருந்தவில்லை.','Re-verify'=>'மீண்டும் சரிபார்','Rebuild index now'=>'இப்போது சுட்டியை மீண்டும் உருவாக்கு','Refusing to write outside the Babilim language-file directory.'=>'Babilim மொழிக் கோப்பு கோப்பகத்திற்கு வெளியே எழுத மறுக்கப்பட்டது.','Registration response was missing required fields.'=>'பதிவு பதிலில் தேவையான புலங்கள் இல்லை.','Registration restarted.'=>'பதிவு மீண்டும் தொடங்கப்பட்டது.','Remove'=>'அகற்று','Remove everything Babilim installed'=>'Babilim நிறுவிய அனைத்தையும் அகற்று','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim நிறுவிய அனைத்தையும் அகற்றவா? இந்தத் தளத்தில் உள்ள ஒவ்வொரு செருகுநிரலுக்கும் தீமுக்கும் அது நிறுவிய அனைத்து மொழிக் கோப்புகளும் நீக்கப்படும்.','Remove the %2$s translation of %1$s from this site?'=>'%1$s இன் %2$s மொழிபெயர்ப்பை இந்தத் தளத்திலிருந்து அகற்றவா?','Removed %d installed component.'=>'நிறுவப்பட்ட %d கூறு அகற்றப்பட்டது.' . "\0" . 'நிறுவப்பட்ட %d கூறுகள் அகற்றப்பட்டன.','Removed after a failed integrity check'=>'ஒருமைப்பாட்டுச் சரிபார்ப்பு தோல்வியடைந்ததால் அகற்றப்பட்டது','Removed.'=>'அகற்றப்பட்டது.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'இந்தத் தளத்தில் உள்ள ஒவ்வொரு செருகுநிரலுக்கும் தீமுக்கும் Babilim நிறுவிய அனைத்து மொழிக் கோப்புகளையும் அகற்றும்.','Report a problem'=>'சிக்கலைப் புகாரளி','Report translation'=>'மொழிபெயர்ப்பைப் புகாரளி','Request newer translation'=>'புதிய மொழிபெயர்ப்பைக் கோரு','Request translation'=>'மொழிபெயர்ப்பைக் கோருக','Requestable'=>'கோரக்கூடியது','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'மொழிபெயர்ப்பைக் கோருவது, இந்தச் செருகுநிரல் அல்லது தீமை இந்தத் தளத்திற்கான இலவச சேவைத் திட்டத்தின் இடஒதுக்கீடுகளில் ஒன்றில் சேர்க்கும் (வரம்பு: தீம்களுக்கு %1$d, செருகுநிரல்களுக்கு %2$d), ஏற்கெனவே அது ஒன்றில் இல்லாவிட்டால். இடஒதுக்கீடு பயன்பாட்டிலேயே இருக்கும்; தோல்வியடைந்த மொழிபெயர்ப்பும் அதை விடுவிக்காது.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'மொழிபெயர்ப்பைக் கோருவது, இந்தச் செருகுநிரல் அல்லது தீமை இந்தத் தளத்திற்கான இலவச சேவைத் திட்டத்தின் இடஒதுக்கீடுகளில் ஒன்றில் சேர்க்கும், ஏற்கெனவே அது ஒன்றில் இல்லாவிட்டால். இடஒதுக்கீடு பயன்பாட்டிலேயே இருக்கும்; தோல்வியடைந்த மொழிபெயர்ப்பும் அதை விடுவிக்காது.','Requesting…'=>'கோருகிறது…','Restart registration'=>'பதிவை மீண்டும் தொடங்கவும்','Restore code'=>'மீட்டெடுப்புக் குறியீடு','Restore purchase'=>'கொள்முதலை மீட்டெடு','Retry request'=>'கோரிக்கையை மீண்டும் முயல்க','Roll back'=>'முந்தைய நிலைக்கு மாற்று','Roll back and report'=>'முந்தைய நிலைக்கு மாற்றி புகாரளி','Roll back and send report'=>'பின்னுருட்டி அறிக்கை அனுப்பு','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s இன் %2$s மொழிபெயர்ப்பை முந்தைய பில்டுக்குத் திரும்பப் பெறவா?','Rolled back and reported.'=>'மீட்டமைக்கப்பட்டு புகாரளிக்கப்பட்டது.','Rolled back to the previous build.'=>'முந்தைய பதிப்பிற்கு மீட்டமைக்கப்பட்டது.','Rolled back, but the report could not be sent: %s'=>'மீட்டமைக்கப்பட்டது, ஆனால் புகாரை அனுப்ப முடியவில்லை: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'முந்தைய நிலைக்கு மீட்டமைத்தால் \'%1$s\' (%2$s) மேலெழுதப்படும்; அது இப்போது நிறுவப்பட்ட மற்றொரு கூறுக்காக (%3$s) வழங்கப்படுகிறது; எதுவும் மாற்றப்படவில்லை.','Rotate-token response was missing site_token.'=>'டோக்கன் சுழற்சிப் பதிலில் site_token இல்லை.','Save changes'=>'மாற்றங்களைச் சேமி','Scheduled, waiting to be processed'=>'திட்டமிடப்பட்டது, செயலாக்கத்திற்காகக் காத்திருக்கிறது','Search'=>'தேடு','Search components'=>'கூறுகளைத் தேடு','Search the installed translations'=>'நிறுவப்பட்ட மொழிபெயர்ப்புகளில் தேடு','Select all'=>'அனைத்தையும் தேர்ந்தெடு','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'குறைவான கூறுகளைத் தேர்ந்தெடுக்கவும்: ஒரு முறைக்கு அதிகபட்சம் %1$d செயல்பாடுகள் (நீங்கள் %2$d தேர்ந்தெடுத்துள்ளீர்கள்).','Send report'=>'அறிக்கையை அனுப்பு','Service plan'=>'சேவைத் திட்டம்','Settings'=>'அமைப்புகள்','Share error reports'=>'பிழை அறிக்கைகளைப் பகிர்','Share this report'=>'இந்த அறிக்கையைப் பகிர்','Show a new restore code'=>'புதிய மீட்டெடுப்புக் குறியீட்டைக் காட்டு','Show the "Report translation" entry in the admin toolbar'=>'நிர்வாகக் கருவிப்பட்டையில் "மொழிபெயர்ப்பைப் புகாரளி" உள்ளீட்டைக் காட்டு','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'இந்தக் கூறின் சில உரைகள் அதன் ஆசிரியரால் நேரடியாக எழுதப்பட்டுள்ளன, அவற்றை மொழித் தொகுப்பால் மொழிபெயர்க்க முடியாது.','Status'=>'நிலை','Status unknown'=>'நிலை தெரியவில்லை','String context'=>'சரத்தின் சூழல்','Suggested translation'=>'பரிந்துரைக்கப்பட்ட மொழிபெயர்ப்பு','Supplementary translation index'=>'துணை மொழிபெயர்ப்புச் சுட்டெண்','Supplementary translation index rebuilt.'=>'துணை மொழிபெயர்ப்புச் சுட்டெண் மீண்டும் உருவாக்கப்பட்டது.','Supplementary translation maintenance'=>'துணை மொழிபெயர்ப்பு பராமரிப்பு','Supplementary translations'=>'துணை மொழிபெயர்ப்புகள்','Sweep aborted without orphaning anything: %s.'=>'எதையும் அனாதையாக்காமல் துடைப்பு நிறுத்தப்பட்டது: %s.','Sweep complete: %d file deleted.'=>'துப்புரவு முடிந்தது: %d கோப்பு நீக்கப்பட்டது.' . "\0" . 'துப்புரவு முடிந்தது: %d கோப்புகள் நீக்கப்பட்டன.','Sweep now'=>'இப்போது துப்புரவு செய்','Sync complete.'=>'ஒத்திசைவு முடிந்தது.','Thank you. Your report was sent.'=>'நன்றி. உங்கள் புகார் அனுப்பப்பட்டது.','That component is not installed on this site, so a translation cannot be requested for it.'=>'அந்தக் கூறு இந்தத் தளத்தில் நிறுவப்படவில்லை, எனவே அதற்கு மொழிபெயர்ப்பைக் கோர முடியாது.','That does not look like a restore code.'=>'இது மீட்டெடுப்புக் குறியீடு போலத் தெரியவில்லை.','That is not a valid WordPress locale code. Nothing was saved.'=>'இது செல்லுபடியாகும் WordPress மொழிக் குறியீடு அல்ல. எதுவும் சேமிக்கப்படவில்லை.','That is not a valid build identifier.'=>'அது சரியான பில்ட் அடையாளங்காட்டி அல்ல.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'அந்தப் பதிவேற்றத் திரை காலாவதியானது: அதற்குப் பிறகு வேறொரு பதிவேற்றம் தயாரிக்கப்பட்டுள்ளது. எதுவும் அனுப்பப்படவில்லை. தற்போதையதை மொழிபெயர்ப்புகள் பட்டியலில் இருந்து மதிப்பாய்வு செய்யவும்.','The change could not be recorded in the translation index; please try again.'=>'மாற்றத்தை மொழிபெயர்ப்புச் சுட்டெண்ணில் பதிவு செய்ய இயலவில்லை; மீண்டும் முயலவும்.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'சுத்தம் செய்தல் இயங்கியது, ஆனால் அதன் சில மாற்றங்களை மொழிபெயர்ப்புச் சுட்டெண்ணில் பதிவு செய்ய முடியவில்லை; அடுத்த சுத்தம் செய்தல் அவற்றை மீண்டும் முயலும்.','The component has no files that can be uploaded.'=>'இந்தக் கூறில் பதிவேற்றக்கூடிய கோப்புகள் எதுவும் இல்லை.','The component is not inside the plugins or themes directory.'=>'கூறு செருகுநிரல்கள் அல்லது தீம்கள் கோப்பகத்தில் இல்லை.','The component\'s main file was not found.'=>'கூறின் முதன்மைக் கோப்பு கிடைக்கவில்லை.','The download response was missing a usable location.'=>'பதிவிறக்க பதிலில் பயன்படுத்தக்கூடிய இருப்பிடம் இல்லை.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'இந்த உள்ளீடு, இந்தத் தளத்தில் Babilim நிறுவிய மொழிபெயர்ப்புகளைத் தேடி அவற்றில் ஒன்றைப் புகாரளிக்கும் பலகத்தைத் திறக்கும்.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" புலம் மிக நீளமாக உள்ளது: அதில் %2$d எழுத்துகள் உள்ளன, வரம்பு %3$d. எதுவும் அனுப்பப்படவில்லை; தயவுசெய்து சுருக்கி மீண்டும் முயலவும்.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'இலவச சேவைத் திட்டம் ஒவ்வொரு தளத்திற்கும் செருகுநிரல்கள் மற்றும் தீம்களுக்கு வரையறுக்கப்பட்ட எண்ணிக்கையிலான இடஒதுக்கீடுகளை வழங்குகிறது; Babilim ஐ இயக்கிய பிறகு பயன்பாட்டில் உள்ள இடஒதுக்கீடுகள் அமைப்புகளில் காட்டப்படும்.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'கொடுக்கப்பட்ட டொமைன் \'%1$s\' தொகுப்பு மேனிஃபெஸ்டின் ஸ்லக் \'%2$s\' அல்லது அதன் text_domain \'%3$s\' இரண்டுடனும் பொருந்தவில்லை.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' க்கான ஒன்றிணைந்த சுட்டெண் மீண்டும் உருவாக்கப்பட்டது, ஆனால் மொழிபெயர்ப்புச் சுட்டெண்ணால் அதைப் பதிவு செய்ய முடியவில்லை; அடுத்த மறுகட்டமைப்பு மீண்டும் முயலும்.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'மூல உரையும் அதிலிருந்து உருவாக்கப்பட்ட மொழிபெயர்ப்புகளும் அதே பதிப்பை நிறுவும் பிற தளங்களுக்கு வழங்கப்படும்.','The package declares no main translation file.'=>'தொகுப்பு முதன்மை மொழிபெயர்ப்புக் கோப்பை அறிவிக்கவில்லை.','The package has no %s for its own text domain.'=>'தொகுப்பில் அதன் சொந்த உரை டொமைனுக்கான %s இல்லை.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'தொகுப்பு மேனிஃபெஸ்டின் வகை \'%1$s\' கோரப்பட்ட வகை \'%2$s\' உடன் பொருந்தவில்லை.','The package produced no servable main translation file.'=>'தொகுப்பு வழங்கக்கூடிய முதன்மை மொழிபெயர்ப்புக் கோப்பை உருவாக்கவில்லை.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'தொகுப்பின் உரை டொமைன் \'%1$s\' இந்தத் தளத்தின் கூறு நகலுடன் (\'%2$s\') பொருந்தவில்லை, எனவே அது நிறுவப்படவில்லை.','The packaged component could not be read.'=>'தொகுக்கப்பட்ட கூறைப் படிக்க முடியவில்லை.','The registration challenge is not in the expected form.'=>'பதிவுச் சவால் எதிர்பார்க்கப்பட்ட வடிவத்தில் இல்லை.','The report could not be sent.'=>'அறிக்கையை அனுப்ப இயலவில்லை.','The search could not be completed.'=>'தேடலை முடிக்க இயலவில்லை.','The service asked this site to wait before syncing again.'=>'மீண்டும் ஒத்திசைப்பதற்கு முன் காத்திருக்குமாறு சேவை இந்தத் தளத்தைக் கேட்டுக்கொண்டது.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'சேவையால் உங்கள் தளத்தை அணுக முடியவில்லை. ஃபயர்வால், பாதுகாப்புச் செருகுநிரல் அல்லது ஹோஸ்ட் விதி அந்தக் கோரிக்கையைத் தடுக்கக்கூடும்; /wp-json/babilim/v1/challenge க்கான கோரிக்கைகளை அனுமதிக்கவும்.','The service\'s upload offer was incomplete.'=>'சேவை வழங்கிய பதிவேற்ற விவரங்கள் முழுமையாக இல்லை.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'உரை டொமைன் \'%1$s\' (%2$s) ஏற்கெனவே மற்றொரு நிறுவப்பட்ட கூறுக்காக (%3$s) வழங்கப்படுகிறது; எதுவும் நிறுவப்படவில்லை.','The upload is kept until you ask Babilim to delete it.'=>'நீங்கள் Babilim-இடம் நீக்கக் கோரும் வரை பதிவேற்றம் வைத்திருக்கப்படும்.','Theme'=>'தீம்','Theme · %s'=>'தீம் · %s','Themes'=>'தீம்கள்','There is no upload in progress.'=>'நடப்பில் உள்ள பதிவேற்றம் எதுவும் இல்லை.','There is no upload waiting for confirmation.'=>'உறுதிப்படுத்தலுக்காகக் காத்திருக்கும் பதிவேற்றம் எதுவும் இல்லை.','These are the languages this site uses. You can change them in %s.'=>'இந்தத் தளம் பயன்படுத்தும் மொழிகள் இவை. நீங்கள் அவற்றை %s இல் மாற்றலாம்.','These fields will be sent:'=>'இந்தப் புலங்கள் அனுப்பப்படும்:','This build is not one this site currently knows about for this component/locale.'=>'இந்தக் கூறு/மொழிக்கு இந்தத் தளம் தற்போது அறிந்த பதிப்புகளில் இது ஒன்றல்ல.','This component does not declare a version number, so a translation cannot be requested for it.'=>'இந்தக் கூறு பதிப்பு எண்ணை அறிவிக்கவில்லை, எனவே அதற்கு மொழிபெயர்ப்பைக் கோர முடியாது.','This component is larger than the service accepts, so it cannot be uploaded.'=>'இந்தக் கூறு சேவை ஏற்கும் அளவை விடப் பெரியது, எனவே பதிவேற்ற முடியாது.','This component was already uploaded. Babilim is checking it now.'=>'இந்தக் கூறு ஏற்கனவே பதிவேற்றப்பட்டுள்ளது. Babilim இப்போது அதைச் சரிபார்க்கிறது.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'இந்தக் கூறின் பதிப்பு எண் %d எழுத்துகளை விட நீளமாக உள்ளது, இதை Babilim கையாள முடியாது, எனவே அதற்கு மொழிபெயர்ப்பைக் கோர முடியாது.','This issues a new restore code and the previous one stops working. Continue?'=>'இது புதிய மீட்டெடுப்புக் குறியீட்டை வழங்கும், முந்தையது செயல்படாது. தொடரவா?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'இந்த நெட்வொர்க்கில் தளங்கள் மிக அதிகமாக இருப்பதால் அவற்றை ஒவ்வொன்றாகச் சரிபார்க்க முடியாது; அவற்றில் சில, செருகுநிரல் நீக்கப்படும்போது தங்கள் Babilim அடையாளத்தை அழிக்கும்படி அமைக்கப்பட்டிருக்கலாம். அத்தகைய தளத்துடன் இணைக்கப்பட்ட கட்டண உரிமத்தை அதன்பிறகு தானாக மீட்டெடுக்க முடியாது; %s என்ற முகவரியில் Babilim ஆதரவைத் தொடர்பு கொள்ள வேண்டும். அடையாளங்களைத் தக்கவைக்க, ரத்துசெய் என்பதை அழுத்தி, ஒவ்வொரு தளத்தின் Babilim அமைப்புகளிலும் "நிறுவல் நீக்கும்போது Babilim தரவு அனைத்தையும் நீக்கு" என்பதைத் தேர்வுநீக்கி, மீண்டும் செயலிழக்கச் செய்யுங்கள். எப்படியும் செயலிழக்கச் செய்யவா?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'இந்தச் செருகுநிரலின் சொந்தப் பதிப்பு, இது மிகவும் பழையதாக இருந்து சேவையுடன் தொடர்பு கொள்ள முடியாவிட்டால் புதுப்பிக்கச் சொல்வதற்காக.','This report does not name a valid plugin or theme and locale.'=>'இந்தப் புகார் செல்லுபடியாகும் செருகுநிரல் அல்லது தீம் மற்றும் மொழியைக் குறிப்பிடவில்லை.','This report does not name an installed string.'=>'இந்த அறிக்கை நிறுவப்பட்ட சரம் எதையும் குறிப்பிடவில்லை.','This report is missing a valid build to report against.'=>'இந்தப் புகாருடன் தொடர்புடைய செல்லுபடியான உருவாக்கப் பதிப்பு இல்லை.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'இந்த அறிக்கை GitHub-இல் பொதுவில் இடுகையிடப்படும்; மூன்றாம் தரப்பினரால் வைத்திருக்கப்படவும் கூடும்.','This restore code was not recognised for this site.'=>'இந்தத் தளத்திற்கு இந்த மீட்டெடுப்புக் குறியீடு அங்கீகரிக்கப்படவில்லை.','This site already has an active registration that can no longer be recovered automatically.'=>'இந்தத் தளத்திற்கு ஏற்கனவே செயலில் உள்ள பதிவு உள்ளது; அதைத் தானாக மீட்டெடுக்க இனி இயலாது.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'இந்தத் தளத்தில் %2$d மொழிகளில் %1$d கூறுகள் உள்ளன, இதற்கு %3$d சரிபார்ப்புத் தொகுதிகள் தேவை; Babilim ஒரு முறை இயக்கத்தில் அதிகபட்சம் %4$d தொகுதிகளைக் கையாளும். அமைப்புகளில் நிர்வகிக்கப்படும் மொழிகளைக் குறைக்கவும் அல்லது பயன்படுத்தாத செருகுநிரல்கள் மற்றும் தீம்களை முடக்கவும், பின்னர் இப்போது மீண்டும் சரிபார் என்பதை அழுத்தவும்.','This site has no purchase to show a code for.'=>'குறியீட்டைக் காட்ட இந்தத் தளத்தில் கொள்முதல் எதுவும் இல்லை.','This site is already licensed. Reload the page.'=>'இந்தத் தளத்திற்கு ஏற்கனவே உரிமம் உள்ளது. பக்கத்தை மீண்டும் ஏற்றவும்.','This site is not registered with Babilim yet.'=>'இந்தத் தளம் இன்னும் Babilim-இல் பதிவு செய்யப்படவில்லை.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'இந்தத் தளம் ஒரே ஒத்திசைவில் சேவை ஏற்கும் அளவை மீறுகிறது, எனவே சில உருப்படிகள் விடப்பட்டன: %1$d கூறுகள் மற்றும் %2$d மொழிகள்.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'இந்தத் தளம் பல்தள நெட்வொர்க்கின் ஒரு பகுதியாகும்; இது புதிய மொழிபெயர்ப்புகளைத் தானாக நிறுவாது. ஏற்கனவே நிறுவப்பட்ட மொழிபெயர்ப்புகள் தொடர்ந்து புதுப்பிக்கப்படும்.','This site is verified.'=>'இந்தத் தளம் சரிபார்க்கப்பட்டது.','This site must be verified first.'=>'இந்தத் தளம் முதலில் சரிபார்க்கப்பட வேண்டும்.','This site\'s URL, so the service can verify you own it.'=>'இந்தத் தளத்தின் URL, இதனால் இதன் உரிமையாளர் நீங்கள்தான் என்பதை சேவை சரிபார்க்க முடியும்.','This site\'s address is too long for Babilim to register.'=>'இந்தத் தளத்தின் முகவரி Babilim பதிவு செய்ய முடியாத அளவு நீளமாக உள்ளது.','This site\'s configured locale.'=>'இந்தத் தளத்தில் கட்டமைக்கப்பட்ட மொழிப்பகுதி.','This site\'s locale code is not one Babilim can register.'=>'இந்தத் தளத்தின் மொழிக் குறியீட்டை Babilim பதிவு செய்ய முடியாது.','This string can\'t be reported from this site.'=>'இந்தச் சரத்தை இந்தத் தளத்திலிருந்து புகாரளிக்க இயலாது.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'இந்தச் சரம் இந்தத் தளத்தில் நிறுவப்பட்ட மொழிபெயர்ப்புகளில் இல்லை. மீண்டும் தேடி, பட்டியலிலிருந்து அதைத் தேர்ந்தெடுக்கவும்.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'நீங்கள் தேடிய பிறகு இந்த மொழிபெயர்ப்பு புதுப்பிக்கப்பட்டது. மீண்டும் தேடி, புதிய பட்டியலிலிருந்து சரத்தைத் தேர்ந்தெடுக்கவும்.','To translate this component, Babilim needs its source.'=>'இந்தக் கூறை மொழிபெயர்க்க, Babilim-க்கு அதன் மூலம் தேவை.','Too many attempts. Try again tomorrow.'=>'அதிக முயற்சிகள். நாளை மீண்டும் முயலவும்.','Too many reports today. Try again tomorrow.'=>'இன்று மிக அதிக அறிக்கைகள் உள்ளன. நாளை மீண்டும் முயலவும்.','Too many requests.'=>'அதிகமான கோரிக்கைகள்.','Toolbar'=>'கருவிப்பட்டை','Translating…'=>'மொழிபெயர்க்கிறது…','Translation does not load'=>'மொழிபெயர்ப்பு ஏற்றப்படவில்லை','Translation failed'=>'மொழிபெயர்ப்பு தோல்வியடைந்தது','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'நீங்கள் %s இல் வைக்கும் மொழிபெயர்ப்புக் கோப்புகள் எப்போதும் Babilim கோப்புகளை விட முன்னுரிமை பெறும். இதைத் தேர்வுநீக்காவிட்டால் அவை வைத்திருக்கப்படும்.','Translation requested.'=>'மொழிபெயர்ப்பு கோரப்பட்டது.','Translations'=>'மொழிபெயர்ப்புகள்','Type'=>'வகை','Type at least 2 characters to search.'=>'தேட குறைந்தது 2 எழுத்துகளை உள்ளிடவும்.','Unexpected HTTP %d response.'=>'எதிர்பாராத HTTP %d பதில்.','Uninstall'=>'நீக்கம்','Unknown kind: %s'=>'அறியப்படாத வகை: %s','Unsafe domain: %s'=>'பாதுகாப்பற்ற டொமைன்: %s','Unsafe locale: %s'=>'பாதுகாப்பற்ற மொழிப்பகுதி: %s','Unsafe slug: %s'=>'பாதுகாப்பற்ற ஸ்லக்: %s','Unsafe text_domain: %s'=>'பாதுகாப்பற்ற text_domain: %s','Update'=>'புதுப்பி','Update available'=>'புதுப்பிப்பு உள்ளது','Updates'=>'புதுப்பிப்புகள்','Updating…'=>'புதுப்பிக்கிறது…','Upgrade this site'=>'இந்தத் தளத்தை மேம்படுத்து','Upload and request'=>'பதிவேற்றிக் கோரு','Upload cancelled.'=>'பதிவேற்றம் ரத்து செய்யப்பட்டது.','Upload complete — translation requested.'=>'பதிவேற்றம் முடிந்தது — மொழிபெயர்ப்பு கோரப்பட்டது.','Upload expired before it finished'=>'பதிவேற்றம் முடிவதற்குள் காலாவதியானது','Upload in progress — continue or cancel'=>'பதிவேற்றம் நடைபெறுகிறது — தொடரவும் அல்லது ரத்துசெய்யவும்','Upload this component?'=>'இந்தக் கூறைப் பதிவேற்றவா?','Upload was not accepted'=>'பதிவேற்றம் ஏற்றுக்கொள்ளப்படவில்லை','Uploading'=>'பதிவேற்றுகிறது','Uploading part %1$d of %2$d…'=>'%2$d இல் %1$d ஆவது பகுதியைப் பதிவேற்றுகிறது…','Uploading…'=>'பதிவேற்றுகிறது…','Verified'=>'சரிபார்க்கப்பட்டது','Verify response was missing site_token.'=>'சரிபார்ப்புப் பதிலில் site_token இல்லை.','Version %s'=>'பதிப்பு %s','What is sent when you enable Babilim'=>'Babilim ஐ இயக்கும்போது அனுப்பப்படுவது','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Babilim-க்குள் ஏதேனும் தோல்வியடையும்போது, அதை GitHub-இல் பொதுப் பிரச்சினையாக வெளியிடுவதற்காக Babilim சேவைக்குப் பிழை அறிக்கையை அனுப்பவும். இந்த அறிக்கை இந்தத் தளத்திலிருந்து வந்ததாக, Babilim சேவைக்கான மற்ற ஒவ்வொரு கோரிக்கையின் அதே அங்கீகாரத்துடன் அனுப்பப்படும். சேவை பிழைக் குறியீட்டையும் பதிப்புகளையும் மட்டுமே GitHub-இல் பொதுப் பிரச்சினையாக வெளியிடும்; அந்தப் பொதுப் பிரச்சினையில் தள முகவரி, உள்ளடக்கம் அல்லது கோப்புப் பாதைகள் எதுவும் இருக்காது. இயல்பாக முடக்கப்பட்டுள்ளது.','Where you saw this (optional)'=>'இதை எங்கு பார்த்தீர்கள் (விருப்பத்திற்குரியது)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'இது இயக்கத்தில் இருக்கும்போது, நீங்கள் நிர்வகிக்கும் மொழிகளுக்குச் சேவை கிடைப்பதாகப் பட்டியலிடும் மொழிபெயர்ப்புகள் தினமும் இருமுறை ஒத்திசைவின்போது நிறுவப்படும்.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'இந்தச் சூழலுக்குத் தவறானது','Wrong meaning'=>'தவறான பொருள்','Wrong plural form'=>'தவறான பன்மை வடிவம்','Wrong term'=>'தவறான சொல்','Yes'=>'ஆம்','You are not allowed to do this.'=>'இதைச் செய்ய உங்களுக்கு அனுமதி இல்லை.','Your PHP version, for compatibility.'=>'உங்கள் PHP பதிப்பு, இணக்கத்தன்மைக்காக.','Your WordPress version, to serve compatible translation files.'=>'உங்கள் WordPress பதிப்பு, இணக்கமான மொழிபெயர்ப்புக் கோப்புகளை வழங்குவதற்காக.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'உங்கள் புதிய மீட்டெடுப்புக் குறியீடு: %s. இதைப் பாதுகாப்பான இடத்தில் வைக்கவும் — முந்தைய குறியீடு இனி செயல்படாது.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'உங்கள் அறிக்கை AI மாதிரிகளால் தானாகச் செயலாக்கப்படுகிறது; மற்ற தளங்களுக்கு இந்த மொழிபெயர்ப்பை மேம்படுத்தவும் கூடும்.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'உங்கள் தளம் பதிலளித்தது, ஆனால் எதிர்பார்த்த பதிலுடன் அல்ல. REST API வேறொரு செருகுநிரலால் மாற்றி எழுதப்பட்டிருக்கலாம், அல்லது அந்த எண்ட்பாயிண்ட் கேச் செய்யப்பட்டிருக்கலாம்; /wp-json/babilim/v1/challenge ஐ கேச்சிங் மற்றும் மாற்றி எழுதுதலிலிருந்து விலக்கவும்.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'உங்கள் தளம் பதிலளிக்க அதிக நேரம் எடுத்தது. பின்னர் மீண்டும் முயற்சிக்கவும், உங்கள் ஹோஸ்ட் மிகவும் மெதுவாகவோ அதிகச் சுமையுடனோ இல்லை என்பதைச் சரிபார்க்கவும்.','Zip has no manifest.json.'=>'ZIP இல் manifest.json இல்லை.','Zip is missing expected default file: %s'=>'எதிர்பார்க்கப்பட்ட இயல்பிருப்புக் கோப்பு zip இல் இல்லை: %s','Zip is missing expected file: %s'=>'எதிர்பார்க்கப்பட்ட கோப்பு zip இல் இல்லை: %s','_manifest.json has an unexpected structure'=>'_manifest.json எதிர்பாராத கட்டமைப்பைக் கொண்டுள்ளது','could not read _manifest.json: %s'=>'_manifest.json ஐப் படிக்க முடியவில்லை: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest இல் \'%s\' இல்லை அல்லது அது தவறானது.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest இன் \'server_build_id\' செல்லுபடியாகும் பில்ட் அடையாளம் அல்ல.','failed to parse _manifest.json: %s'=>'_manifest.json ஐ பகுப்பாய்வு செய்ய முடியவில்லை: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'இது நிர்வகிக்கப்படும் %2$d கூறுகளில் %1$d ஐ அனாதையாக்கிவிடும் (பாதிக்கு மேல்)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'இது நிர்வகிக்கப்படும் ஒவ்வொரு %1$s கூறையும் (%2$d இல் %2$d) அனாதையாக்கிவிடும்','l10n.php entry count mismatch for %s'=>'%s க்கான l10n.php உள்ளீட்டு எண்ணிக்கை பொருந்தவில்லை','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json இல் தவறான \'default_domain_entries\' உள்ளது.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json இல் தவறான \'default_domain_files\' உள்ளது.','manifest.json in the zip is not valid JSON.'=>'ZIP இலுள்ள manifest.json சரியான JSON அல்ல.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json இல் \'%s\' இல்லை அல்லது தவறானது.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json இல் \'build_no\' இல்லை அல்லது அது தவறானது.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json இல் \'entries\' இல்லை அல்லது அது தவறானது.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json இல் \'extra_domains\' இல்லை அல்லது அது தவறானது.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json இல் \'files\' இல்லை அல்லது அது தவறானது.','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json இன் \'%s\' எதிர்பார்க்கப்படும் மதிப்புடன் பொருந்தவில்லை.','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json இன் \'contract\' செல்லுபடியாகும் பதிப்புச் சரம் அல்ல.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json இன் \'kind\' \'plugin\' அல்லது \'theme\' ஆக இருக்க வேண்டும்.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json இன் \'server_build_id\' செல்லுபடியாகும் பில்ட் அடையாளம் அல்ல.','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json இன் \'status\' \'published\' ஆக இருக்க வேண்டும்.','nonce must be a hexadecimal string.'=>'நான்ஸ் ஒரு பதினறும எண் சரமாக இருக்க வேண்டும்.','per day'=>'ஒரு நாளைக்கு','rc_…'=>'rc_…','sha256 mismatch for %s'=>'%s க்கு sha256 பொருந்தவில்லை','sha256 mismatch for default/%s'=>'default/%s க்கு sha256 பொருந்தவில்லை','component kind in the sweep brake messageplugin'=>'செருகுநிரல்','component kind in the sweep brake messagetheme'=>'தீம்','problem report categoryOther'=>'மற்றவை','translation statusAvailable'=>'கிடைக்கிறது','translation statusInstalled'=>'நிறுவப்பட்டது','Babilim translation turned off.'=>'Babilim மொழிபெயர்ப்பு அணைக்கப்பட்டது.','Stop using Babilim translation'=>'Babilim மொழிபெயர்ப்பைப் பயன்படுத்துவதை நிறுத்து','Use Babilim translation'=>'Babilim மொழிபெயர்ப்பைப் பயன்படுத்து','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the theme\'s own or WordPress.org translation instead. You can switch back at any time.'=>'%1$s (%2$s) என்பதற்கான Babilim மொழிபெயர்ப்பைப் பயன்படுத்துவதை நிறுத்தவா? அதற்குப் பதிலாக WordPress தீமின் சொந்த மொழிபெயர்ப்பை அல்லது WordPress.org மொழிபெயர்ப்பைப் பயன்படுத்தும். நீங்கள் எப்போது வேண்டுமானாலும் மீண்டும் மாற்றிக்கொள்ளலாம்.','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the plugin\'s own or WordPress.org translation instead. You can switch back at any time.'=>'%1$s (%2$s) என்பதற்கான Babilim மொழிபெயர்ப்பைப் பயன்படுத்துவதை நிறுத்தவா? அதற்குப் பதிலாக WordPress செருகுநிரலின் சொந்த மொழிபெயர்ப்பை அல்லது WordPress.org மொழிபெயர்ப்பைப் பயன்படுத்தும். நீங்கள் எப்போது வேண்டுமானாலும் மீண்டும் மாற்றிக்கொள்ளலாம்.']];